@* ===================== Security Section ===================== *@
@{
    RenderFragment RenderSecuritySection() =>
        @<div class="settings-section">
            <h3>Security</h3>
            <p class="text-muted">Manage your account security</p>
            <hr />

            <!-- Change Password Panel -->
            <div class="expandable-panel mb-4">
                <button class="btn btn-outline-secondary w-100 text-start d-flex justify-content-between align-items-center"
                        @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
                    <span><strong>Change Password</strong></span>
                    <span>@(_passwordPanelOpen ? "▲" : "▼")</span>
                </button>

                @if (_passwordPanelOpen)
                {
                    <div class="panel-body mt-3">
                        <div class="mb-3">
                            <label class="form-label">Current Password</label>
                            <input type="password" class="form-control" @bind="_currentPassword" />
                        </div>
                        <div class="mb-3">
                            <label class="form-label">New Password</label>
                            <input type="password" class="form-control" @bind="_newPassword" />
                        </div>
                        <div class="mb-3">
                            <label class="form-label">Confirm New Password</label>
                            <input type="password" class="form-control" @bind="_confirmPassword" />
                        </div>
                        @if (!string.IsNullOrEmpty(_passwordError))
                        {
                            <div class="alert alert-danger py-2">@_passwordError</div>
                        }
                        <button class="btn btn-primary" @onclick="UpdatePassword">Update Password</button>
                        @if (_securitySettings?.LastPasswordChange is not null)
                        {
                            <p class="text-muted mt-2 mb-0">
                                Last changed: @_securitySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")
                            </p>
                        }
                    </div>
                }
            </div>

            <!-- Two-Factor Authentication -->
            <div class="toggle-row">
                <div>
                    <strong>Two-Factor Authentication</strong>
                    <p class="mb-0">
                        <span class="badge @(_twoFactorEnabled ? "bg-success" : "bg-secondary")">
                            @(_twoFactorEnabled ? "Enabled" : "Disabled")
                        </span>
                    </p>
                </div>
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" role="switch"
                           checked="@_twoFactorEnabled"
                           @onchange="e => _twoFactorEnabled = (bool)e.Value!" />
                </div>
            </div>

            <!-- Active Sessions -->
            <h5 class="mt-4 mb-3">Active Sessions</h5>
            @if (_securitySettings?.Sessions.Count > 0)
            {
                <div class="table-responsive">
                    <table class="table table-hover">
                        <thead>
                            <tr>
                                <th>Device</th>
                                <th>Location</th>
                                <th>Last Active</th>
                                <th></th>
                            </tr>
                        </thead>
                        <tbody>
                            @foreach (var session in _securitySettings.Sessions)
                            {
                                <tr>
                                    <td>@session.Device</td>
                                    <td>@session.Location</td>
                                    <td>@FormatLastActive(session.LastActive)</td>
                                    <td>
                                        @if (session.Id != _securitySettings.Sessions.First().Id)
                                        {
                                            <button class="btn btn-outline-danger btn-sm"
                                                    @onclick="() => PromptRevokeSession(session)">
                                                Revoke
                                            </button>
                                        }
                                        else
                                        {
                                            <span class="badge bg-info">Current</span>
                                        }
                                    </td>
                                </tr>
                            }
                        </tbody>
                    </table>
                </div>
            }

            <!-- Revoke Confirmation Dialog -->
            @if (_sessionToRevoke is not null)
            {
                <div class="modal-backdrop show" @onclick="CancelRevoke"></div>
                <div class="modal d-block" tabindex="-1">
                    <div class="modal-dialog modal-dialog-centered">
                        <div class="modal-content">
                            <div class="modal-header">
                                <h5 class="modal-title">Revoke Session</h5>
                                <button type="button" class="btn-close" @onclick="CancelRevoke"></button>
                            </div>
                            <div class="modal-body">
                                <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> from <strong>@_sessionToRevoke.Location</strong>?</p>
                                <p class="text-muted">This will sign out the device immediately.</p>
                            </div>
                            <div class="modal-footer">
                                <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                                <button class="btn btn-danger" @onclick="ConfirmRevokeSession">Revoke Session</button>
                            </div>
                        </div>
                    </div>
                </div>
            }
        </div>;
}

@* ===================== Appearance Section ===================== *@
@{
    RenderFragment RenderAppearanceSection() =>
        @<div class="settings-section">
            <h3>Appearance</h3>
            <p class="text-muted">Customize the look and feel of the application</p>
            <hr />

            <!-- Theme -->
            <div class="mb-4">
                <h5>Theme</h5>
                <div class="d-flex gap-3">
                    @foreach (var theme in new[] { "Light", "Dark", "System" })
                    {
                        var t = theme;
                        <div class="form-check">
                            <input class="form-check-input" type="radio" name="theme" id="@($"theme-{t}")"
                                   value="@t" checked="@(_appearanceTheme == t)"
                                   @onchange="() => _appearanceTheme = t" />
                            <label class="form-check-label" for="@($"theme-{t}")">@t</label>
                        </div>
                    }
                </div>
            </div>

            <!-- Font Size -->
            <div class="mb-4">
                <h5>Font Size</h5>
                <div class="d-flex gap-3">
                    @foreach (var size in new[] { "Small", "Medium", "Large" })
                    {
                        var s = size;
                        <div class="form-check">
                            <input class="form-check-input" type="radio" name="fontSize" id="@($"fs-{s}")"
                                   value="@s" checked="@(_appearanceFontSize == s)"
                                   @onchange="() => _appearanceFontSize = s" />
                            <label class="form-check-label" for="@($"fs-{s}")">@s</label>
                        </div>
                    }
                </div>
            </div>

            <!-- Language -->
            <div class="mb-4">
                <h5>Language</h5>
                <select class="form-select" style="max-width: 300px;" @bind="_appearanceLanguage">
                    <option value="English">English</option>
                    <option value="Spanish">Spanish</option>
                    <option value="French">French</option>
                    <option value="German">German</option>
                    <option value="Japanese">Japanese</option>
                    <option value="Chinese">Chinese</option>
                    <option value="Portuguese">Portuguese</option>
                </select>
            </div>

            <!-- Compact Mode -->
            <div class="toggle-row mb-4">
                <div>
                    <strong>Compact Mode</strong>
                    <p class="text-muted mb-0">Reduce spacing and padding throughout the interface</p>
                </div>
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" role="switch"
                           checked="@_appearanceCompact"
                           @onchange="e => _appearanceCompact = (bool)e.Value!" />
                </div>
            </div>

            <!-- Live Preview -->
            <div class="mb-4">
                <h5>Preview</h5>
                <div class="appearance-preview @GetPreviewClasses()">
                    <div class="preview-header">
                        <strong>Sample Header</strong>
                    </div>
                    <div class="preview-body">
                        <p>This is a preview of how your content will look with the selected settings.</p>
                        <button class="btn btn-sm @(_appearanceTheme == "Dark" ? "btn-light" : "btn-primary")">
                            Sample Button
                        </button>
                    </div>
                    <div class="preview-footer">
                        <small>Footer content &middot; @_appearanceLanguage &middot; @_appearanceFontSize</small>
                    </div>
                </div>
            </div>

            <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
        </div>;
}

@code {
    private string ActiveSection { get; set; } = "profile";
    private bool _loading = true;

    // Toast
    private string? _toastMessage;
    private bool _toastIsError;
    private CancellationTokenSource? _toastCts;

    // Section metadata
    private readonly Dictionary<string, (string Label, string Icon)> _sections = new()
    {
        ["profile"] = ("Profile", "👤"),
        ["notifications"] = ("Notifications", "🔔"),
        ["security"] = ("Security", "🔒"),
        ["appearance"] = ("Appearance", "🎨"),
    };

    // Profile state
    private string _profileDisplayName = "";
    private string _profileEmail = "";
    private string _profileAvatarUrl = "";
    private string _profileBio = "";
    private UserProfile? _savedProfile;

    // Notifications state
    private bool _notifEmail;
    private bool _notifPush;
    private bool _notifWeeklyDigest;
    private List<ChannelItem> _mutedChannels = new();

    // Security state
    private SecuritySettings? _securitySettings;
    private bool _passwordPanelOpen;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string? _passwordError;
    private bool _twoFactorEnabled;
    private ActiveSession? _sessionToRevoke;

    // Appearance state
    private string _appearanceTheme = "Light";
    private string _appearanceFontSize = "Medium";
    private string _appearanceLanguage = "English";
    private bool _appearanceCompact;

    protected override async Task OnInitializedAsync()
    {
        await LoadAllSettings();
        _loading = false;
    }

    private async Task LoadAllSettings()
    {
        var profileTask = SettingsService.GetProfileAsync();
        var notifTask = SettingsService.GetNotificationPrefsAsync();
        var securityTask = SettingsService.GetSecuritySettingsAsync();
        var appearanceTask = SettingsService.GetAppearanceAsync();

        await Task.WhenAll(profileTask, notifTask, securityTask, appearanceTask);

        // Profile
        _savedProfile = profileTask.Result;
        ApplyProfile(_savedProfile);

        // Notifications
        var notif = notifTask.Result;
        _notifEmail = notif.EmailNotifications;
        _notifPush = notif.PushNotifications;
        _notifWeeklyDigest = notif.WeeklyDigest;
        _mutedChannels = notif.MutedChannels
            .Select(c => new ChannelItem { Name = c, IsMuted = true })
            .ToList();

        // Security
        _securitySettings = securityTask.Result;
        _twoFactorEnabled = _securitySettings.TwoFactorEnabled;

        // Appearance
        var appearance = appearanceTask.Result;
        _appearanceTheme = appearance.Theme;
        _appearanceFontSize = appearance.FontSize;
        _appearanceLanguage = appearance.Language;
        _appearanceCompact = appearance.CompactMode;
    }

    private void ApplyProfile(UserProfile profile)
    {
        _profileDisplayName = profile.DisplayName;
        _profileEmail = profile.Email;
        _profileAvatarUrl = profile.AvatarUrl;
        _profileBio = profile.Bio;
    }

    private void SetActiveSection(string section) => ActiveSection = section;

    // ========== Profile ==========

    private async Task SaveProfile()
    {
        var profile = new UserProfile(_profileDisplayName, _profileEmail, _profileAvatarUrl, _profileBio);
        await SettingsService.SaveProfileAsync(profile);
        _savedProfile = profile;
        ShowToast("Profile saved successfully!");
    }

    private void DiscardProfileChanges()
    {
        if (_savedProfile is not null)
        {
            ApplyProfile(_savedProfile);
            ShowToast("Changes discarded.");
        }
    }

    // ========== Notifications ==========

    private void ToggleChannelMute(string channelName, bool isMuted)
    {
        var ch = _mutedChannels.FirstOrDefault(c => c.Name == channelName);
        if (ch is not null) ch.IsMuted = isMuted;
    }

    private async Task SaveNotifications()
    {
        var mutedNames = _mutedChannels.Where(c => c.IsMuted).Select(c => c.Name).ToList();
        var prefs = new NotificationPrefs(_notifEmail, _notifPush, _notifWeeklyDigest, mutedNames);
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        ShowToast("Notification preferences saved!");
    }

    // ========== Security ==========

    private async Task UpdatePassword()
    {
        _passwordError = null;

        if (string.IsNullOrWhiteSpace(_currentPassword))
        {
            _passwordError = "Current password is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(_newPassword) || _newPassword.Length < 8)
        {
            _passwordError = "New password must be at least 8 characters.";
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            _passwordError = "New passwords do not match.";
            return;
        }

        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
        _passwordPanelOpen = false;
        ShowToast("Password updated successfully!");
    }

    private void PromptRevokeSession(ActiveSession session) => _sessionToRevoke = session;
    private void CancelRevoke() => _sessionToRevoke = null;

    private async Task ConfirmRevokeSession()
    {
        if (_sessionToRevoke is null) return;
        await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        _sessionToRevoke = null;
        ShowToast("Session revoked.");
    }

    // ========== Appearance ==========

    private string GetPreviewClasses()
    {
        var classes = new List<string>();
        classes.Add($"preview-theme-{_appearanceTheme.ToLowerInvariant()}");
        classes.Add($"preview-font-{_appearanceFontSize.ToLowerInvariant()}");
        if (_appearanceCompact) classes.Add("preview-compact");
        return string.Join(" ", classes);
    }

    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(_appearanceTheme, _appearanceFontSize, _appearanceLanguage, _appearanceCompact);
        await SettingsService.SaveAppearanceAsync(settings);
        ShowToast("Appearance settings saved!");
    }

    // ========== Toast ==========

    private async void ShowToast(string message, bool isError = false)
    {
        _toastCts?.Cancel();
        _toastCts = new CancellationTokenSource();
        var token = _toastCts.Token;

        _toastMessage = message;
        _toastIsError = isError;
        StateHasChanged();

        try
        {
            await Task.Delay(3000, token);
            _toastMessage = null;
            StateHasChanged();
        }
        catch (TaskCanceledException) { }
    }

    private void DismissToast() => _toastMessage = null;

    // ========== Helpers ==========

    private static string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }

    public class ChannelItem
    {
        public string Name { get; set; } = "";
        public bool IsMuted { get; set; }
    }
}

.settings-layout {
    display: flex;
    min-height: calc(100vh - 120px);
    gap: 0;
}

/* ===== Sidebar ===== */
.settings-sidebar {
    width: 240px;
    min-width: 240px;
    background: #f8f9fa;
    border-right: 1px solid #dee2e6;
    padding: 1.5rem 0;
}

.sidebar-title {
    padding: 0 1.25rem 1rem;
    margin: 0;
    font-weight: 700;
    color: #495057;
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

.settings-nav {
    list-style: none;
    padding: 0;
    margin: 0;
}

.settings-nav li {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.75rem 1.25rem;
    cursor: pointer;
    color: #495057;
    font-weight: 500;
    transition: background-color 0.15s, color 0.15s;
    border-left: 3px solid transparent;
}

.settings-nav li:hover {
