}

.settings-nav li.active {
    background-color: #e7f1ff;
    color: #0d6efd;
    border-left-color: #0d6efd;
    font-weight: 600;
}

.nav-icon {
    font-size: 1.1rem;
}

/* ===== Content ===== */
.settings-content {
    flex: 1;
    padding: 2rem 2.5rem;
    position: relative;
    max-width: 800px;
}

.settings-section h3 {
    margin-bottom: 0.25rem;
    font-weight: 700;
}

/* ===== Avatar ===== */
.avatar-area {
    display: flex;
    align-items: flex-start;
    gap: 1.5rem;
}

.avatar-preview {
    width: 96px;
    height: 96px;
    border-radius: 50%;
    object-fit: cover;
    border: 3px solid #dee2e6;
    flex-shrink: 0;
}

.avatar-area > div {
    flex: 1;
}

/* ===== Toggle Row ===== */
.toggle-row {
