    }
}

/* ===== Modal backdrop ===== */
::deep .modal-backdrop.show {
    position: fixed;
    inset: 0;
    background: rgba(0,0,0,0.5);
    z-index: 1040;
}

::deep .modal.d-block {
    z-index: 1050;
}

